-- ============================================================
-- BENCHMARK QUERIES & EXECUTION PLAN ANALYSIS
-- ============================================================
-- Query 1: Aggregation across 100,000 items by product
EXPLAIN ANALYZE
SELECT product_id, SUM(quantity) AS units, SUM(quantity * unit_price) AS revenue
FROM order_items
GROUP BY product_id;

-- Query 2: Selective filter on order line items
EXPLAIN ANALYZE
SELECT * FROM order_items WHERE product_id = 1 AND unit_price > 50000;

-- Query 3: Multi-table Join with Customer & Orders at scale
EXPLAIN ANALYZE
SELECT c.city, SUM(oi.quantity * oi.unit_price) AS city_gross
FROM customers c
JOIN orders o ON o.customer_id = c.customer_id
JOIN order_items oi ON oi.order_id = o.order_id
WHERE o.status = 'DELIVERED'
GROUP BY c.city;
